import CategoryProductBrowser from "@/components/category/CategoryProductBrowser";
import type { Product } from "@/types/product";
import { notFound } from "next/navigation";

const API_BASE_URL = process.env.LARAVEL_API_URL ?? "http://127.0.0.1:8001/api";

async function getProducts(): Promise<Product[]> {
  try {
    const response = await fetch(`${API_BASE_URL}/products`, {
      cache: "no-store",
      headers: { Accept: "application/json" },
    });

    if (!response.ok) throw new Error("Không tải được sản phẩm.");
    return await response.json();
  } catch {
    return [];
  }
}

export default async function CategoryPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const categoryMap: Record<string, string> = {
    "nuoc-hoa-nu": "Nước hoa nữ",
    "nuoc-hoa-nam": "Nước hoa nam",
    "unisex": "Unisex",
  };
  const categoryName = categoryMap[slug];

  if (!categoryName) notFound();

  const products = await getProducts();
  const categoryProducts = products.filter((product) => product.category === categoryName);

  return (
    <div className="min-h-[calc(100vh-160px)] bg-[linear-gradient(180deg,#fffaf7_0%,#fff_100%)] py-12 lg:py-16">
      <div className="container mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        <div className="mb-8 border-b border-[#eadfd5] pb-5">
          <p className="text-xs font-semibold uppercase tracking-[0.22em] text-primary">Perfume category</p>
          <h1 className="mt-2 text-3xl font-semibold text-[#2d1d2c]">{categoryName}</h1>
          <p className="mt-2 text-muted-foreground">Có {categoryProducts.length} sản phẩm nguyên chai</p>
        </div>
        <CategoryProductBrowser products={categoryProducts} categoryName={categoryName} />
      </div>
    </div>
  );
}
